INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenbanken > Datentypen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können boolesche Werte in einer Datenbank nur die Werte TRUE oder FALSE annehmen?', 2, '[{"text": "Ja", "correct": true, "because": "Boolesche Werte repräsentieren binäre Zustände"}, {"text": "Nein", "correct": false, "because": "Nur zwei Zustände möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Ganzzahlen in Datenbanken immer auf positive Werte beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Ganzzahlen können positiv, negativ oder null sein"}, {"text": "Ja", "correct": false, "because": "Negative Werte sind erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Gleitkommawerte in Datenbanken immer Dezimalstellen enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Gleitkommawerte können auch Ganzzahlen sein"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Datumswert in einer Datenbank auch Zeitinformationen enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Datentypen wie DATETIME enthalten Datum und Zeit"}, {"text": "Nein", "correct": false, "because": "Zeit ist oft inkludiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind BLOB-Datentypen in Datenbanken ausschließlich für Textdaten geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "BLOBs speichern binäre Daten wie Bilder oder Dateien"}, {"text": "Ja", "correct": false, "because": "Nicht auf Text beschränkt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp wird verwendet, um einen Wahrheitswert wie JA/NEIN zu speichern?', 2, '[{"text": "Boolesch", "correct": true, "because": "Speichert TRUE/FALSE"}, {"text": "Ganzzahl", "correct": false, "because": "Für numerische Werte"}, {"text": "Text", "correct": false, "because": "Für Zeichenketten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp ist am besten geeignet, um Geldbeträge mit fester Dezimalpräzision zu speichern?', 3, '[{"text": "Währung", "correct": true, "because": "Optimiert für Geldbeträge"}, {"text": "Gleitkomma", "correct": false, "because": "Ungenau bei Dezimalwerten"}, {"text": "Ganzzahl", "correct": false, "because": "Keine Dezimalstellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp wird verwendet, um Geokoordinaten wie Breiten- und Längengrade zu speichern?', 2, '[{"text": "Geokoordinaten", "correct": true, "because": "Spezialisierter Typ wie POINT"}, {"text": "Text", "correct": false, "because": "Weniger effizient"}, {"text": "Ganzzahl", "correct": false, "because": "Ungeeignet für Koordinaten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp eignet sich am besten für lange Textpassagen mit variabler Länge?', 2, '[{"text": "Text (variabel)", "correct": true, "because": "VARCHAR für variable Länge"}, {"text": "Text (fest)", "correct": false, "because": "CHAR für feste Länge"}, {"text": "BLOB", "correct": false, "because": "Für binäre Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Datentyp ist ideal für die Speicherung eines Bildes in einer Datenbank?', 2, '[{"text": "BLOB", "correct": true, "because": "Speichert binäre Daten wie Bilder"}, {"text": "Text", "correct": false, "because": "Nur für Zeichenketten"}, {"text": "Datumswert", "correct": false, "because": "Für Zeitangaben"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Datentypen eignen sich für numerische Werte?', 4, '[{"text": "Ganzzahl", "correct": true, "because": "Für ganze Zahlen"}, {"text": "Gleitkomma", "correct": true, "because": "Für Dezimalzahlen"}, {"text": "Währung", "correct": true, "because": "Für Geldbeträge"}, {"text": "Text", "correct": false, "because": "Für Zeichenketten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften charakterisieren variable Textdatentypen?', 3, '[{"text": "Flexible Länge", "correct": true, "because": "VARCHAR passt sich an"}, {"text": "Effiziente Speichernutzung", "correct": true, "because": "Nur benötigter Speicher"}, {"text": "Für kurze Texte optimiert", "correct": true, "because": "Geeignet für variable Inhalte"}, {"text": "Feste Länge", "correct": false, "because": "Typisch für CHAR"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datentypen können Zeit- oder Datumsangaben speichern?', 4, '[{"text": "Datumswert", "correct": true, "because": "Für Datum und Zeit"}, {"text": "Ganzzahl", "correct": true, "because": "Als UNIX-Timestamp möglich"}, {"text": "Text", "correct": true, "because": "Als formatierter String"}, {"text": "BLOB", "correct": false, "because": "Für binäre Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Währungs-Datentyp?', 3, '[{"text": "Feste Dezimalpräzision", "correct": true, "because": "Genau für Geldbeträge"}, {"text": "Vermeidung von Rundungsfehlern", "correct": true, "because": "Präzise Berechnungen"}, {"text": "Währungssymbolspeicherung", "correct": true, "because": "Formatierung möglich"}, {"text": "Flexible Länge", "correct": false, "because": "Feste Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datentypen sind für spezielle Anwendungen geeignet?', 3, '[{"text": "Geokoordinaten", "correct": true, "because": "Für räumliche Daten"}, {"text": "BLOB", "correct": true, "because": "Für binäre Objekte"}, {"text": "Boolesch", "correct": true, "because": "Für binäre Entscheidungen"}, {"text": "Ganzzahl", "correct": false, "because": "Allgemein, nicht spezialisiert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Boolesche Werte speichern binäre Zustände. b) Sie können mehrere Werte gleichzeitig annehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Binär ja, mehrere Werte nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ganzzahlen können negative Werte speichern. b) Gleitkommawerte sind immer ganzzahlig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Negative ja, Gleitkomma flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Währungsdatentypen vermeiden Rundungsfehler. b) Sie sind für lange Texte geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rundungsfehler ja, Texte nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Datumswerte können Zeitangaben enthalten. b) BLOB-Datentypen sind für Geokoordinaten optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit ja, BLOB nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Variable Textdatentypen sind speichereffizient. b) Geokoordinaten sind ausschließlich Ganzzahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Koordinaten Gleitkomma"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

